/** Checkpoint (span event): The agent state changed (`lk.old_state` -> `lk.new_state`). */
export const CHECKPOINT_AGENT_STATE_CHANGED = "agent_state_changed" as const;
/** Checkpoint (span event): The subscriber's SDP answer went out. */
export const CHECKPOINT_ANSWER_SENT = "answer_sent" as const;
/** Checkpoint (span event): A peer connection was created before the join response (JS port only). */
export const CHECKPOINT_EARLY_PC_CREATED = "early_pc_created" as const;
/** Checkpoint (span event): The RTC engine is ready (Swift stamps it with pc_connected). */
export const CHECKPOINT_ENGINE = "engine" as const;
/** Checkpoint (span event): The entrypoint was cancelled. */
export const CHECKPOINT_ENTRYPOINT_CANCELLED = "entrypoint_cancelled" as const;
/** Checkpoint (span event): The entrypoint returned. */
export const CHECKPOINT_ENTRYPOINT_RETURNED = "entrypoint_returned" as const;
/** Checkpoint (span event): The entrypoint started running. */
export const CHECKPOINT_ENTRYPOINT_STARTED = "entrypoint_started" as const;
/** Checkpoint (span event): A synchronous block on the event loop, with `lk.blocking.duration`; mirrors the span of the same name. */
export const CHECKPOINT_EVENT_LOOP_BLOCKED = "event_loop_blocked" as const;
/** Checkpoint (span event): The OTel exception event (`exception.*`), recorded on whichever span the exception was caught on; declared here once. */
export const CHECKPOINT_EXCEPTION = "exception" as const;
/** Checkpoint (span event): The first frame arrived. */
export const CHECKPOINT_FIRST_FRAME = "first_frame" as const;
/** Checkpoint (span event): The first inbound stats reading with bytes; the span ends ok here. */
export const CHECKPOINT_FIRST_MEDIA = "first_media" as const;
/** Checkpoint (span event): OTel GenAI inference details event (the GenAI registry defines it; events cannot be referenced */
export const CHECKPOINT_GEN_AI_CLIENT_INFERENCE_OPERATION_DETAILS = "gen_ai.client.inference.operation.details" as const;
/** Checkpoint (span event): One generation started (the generation attributes). */
export const CHECKPOINT_GENERATION = "generation" as const;
/** Checkpoint (span event): The worker accepted the job. */
export const CHECKPOINT_JOB_ACCEPTED = "job_accepted" as const;
/** Checkpoint (span event): The server assigned the job. */
export const CHECKPOINT_JOB_ASSIGNED = "job_assigned" as const;
/** Checkpoint (span event): The worker received the job request. */
export const CHECKPOINT_JOB_RECEIVED = "job_received" as const;
/** Checkpoint (span event): The server-side job start time, as the worker learned it. */
export const CHECKPOINT_JOB_STARTED_ON_SERVER = "job_started_on_server" as const;
/** Checkpoint (span event): The join response arrived. */
export const CHECKPOINT_JOIN_RECV = "join_recv" as const;
/** Checkpoint (span event): The publisher's SDP offer went out. */
export const CHECKPOINT_OFFER_SENT = "offer_sent" as const;
/** Checkpoint (span event): The linked participant left the room, with `lk.disconnect_reason`. */
export const CHECKPOINT_PARTICIPANT_DISCONNECTED = "participant_disconnected" as const;
/** Checkpoint (span event): The session linked to its participant. */
export const CHECKPOINT_PARTICIPANT_LINKED = "participant_linked" as const;
/** Checkpoint (span event): The primary peer connection connected. */
export const CHECKPOINT_PC_CONNECTED = "pc_connected" as const;
/** Checkpoint (span event): The peer connections exist (stamped once the join is adopted). */
export const CHECKPOINT_PC_CREATED = "pc_created" as const;
/** Checkpoint (span event): Pre-connect audio was replayed, with `lk.pre_connect_audio.duration`. */
export const CHECKPOINT_PRE_CONNECT_AUDIO = "pre_connect_audio" as const;
/** Checkpoint (span event): A preemptive generation was discarded in favour of this one (`lk.speech_id` of the discarded handle). */
export const CHECKPOINT_PREEMPTIVE_GENERATION_DISCARDED = "preemptive_generation_discarded" as const;
/** Checkpoint (span event): A job process was launched for it. */
export const CHECKPOINT_PROCESS_ASSIGNED = "process_assigned" as const;
/** Checkpoint (span event): A later trigger re-armed the wait. */
export const CHECKPOINT_REARMED = "rearmed" as const;
/** Checkpoint (span event): The Room reached the connected state. */
export const CHECKPOINT_ROOM_CONNECTED = "room_connected" as const;
/** Checkpoint (span event): Signaling is up (stamped with ws_open on the web and with join_recv on Swift). */
export const CHECKPOINT_SIGNAL = "signal" as const;
/** Checkpoint (span event): The hook stopped the response. */
export const CHECKPOINT_STOP_RESPONSE = "stop_response" as const;
/** Checkpoint (span event): The platform reported the remote track subscribed. */
export const CHECKPOINT_SUBSCRIBED = "subscribed" as const;
/** Checkpoint (span event): A newer detection superseded this one. */
export const CHECKPOINT_SUPERSEDED = "superseded" as const;
/** Checkpoint (span event): The track was subscribed, with `lk.track_sid` and `lk.track_source`. */
export const CHECKPOINT_TRACK_SUBSCRIBED = "track_subscribed" as const;
/** Checkpoint (span event): The user spoke again during the wait. */
export const CHECKPOINT_USER_RESUMED = "user_resumed" as const;
/** Checkpoint (span event): The user state changed (`lk.old_state` -> `lk.new_state`). */
export const CHECKPOINT_USER_STATE_CHANGED = "user_state_changed" as const;
/** Checkpoint (span event): The signaling WebSocket opened. */
export const CHECKPOINT_WS_OPEN = "ws_open" as const;

